    return `<div class="kw-gloss">${seen.map((k) => `<div><span class="kw kw-${k.tone}">${U.ic(k.icon, '', 'kw-ic')}${k.tip.split(':')[0]}</span> ${k.tip.slice(k.tip.indexOf(':') + 1)}</div>`).join('')}</div>`;
