        const right = i === spans.length - 1 ? `M${W + 10} -10 L${W + 10} ${H + 40}` : seams[i];
        // a closed shape: down the left border, back up the right one
        const pts = (d) => d.match(/-?\d+(\.\d+)?/g).map(Number);
        const l = pts(left),
          r = pts(right);
        const lp = [],
          rp = [];
