      if (['s', 'm', 'l', 'xl'].includes(got.text)) p.text = got.text;
      if (['young', 'always', 'never'].includes(got.hints)) p.hints = got.hints;
      if (typeof got.confirmEnd === 'boolean') p.confirmEnd = got.confirmEnd;
